  add('m_h7', {
    rx: [
      { err: '定積分の上端と下端が逆になっている ∫₂⁰ を、∫₀² と同じ値として計算してしまう。', why: '定積分を「その区間の面積」とだけ思っていて、「上端での値 − 下端での値」という計算の向きを意識していないからです。', fix: '定積分はいつも [F(x)] の「上の値 − 下の値」で計算します。上端と下端を入れかえると、符号が変わる(∫ₐᵇ = −∫ᵇₐ)と覚えておきます。', q: '∫₂⁰ 3x² dx を計算しよう。', a: '−8', exp: '[x³] で上端 0、下端 2 なので、0³ − 2³ = −8 です。∫₀² 3x² dx = 8 の符号が変わった値になります。区間の向きが逆になると、値の符号も逆になります。' },
      { err: '∫₂ˣ f(t) dt を x で微分するとき、f(x) − f(2) としてしまう。', why: '定積分の計算「F(x) − F(2)」の形が頭に残っていて、F を微分すると f になることと、F(2) が定数であることを組み合わせられていないからです。', fix: '∫ₐˣ f(t) dt = F(x) − F(a) と書いてから微分します。F(a) は定数なので微分すると 0 になり、結果は f(x) だけです。', q: '∫₂ˣ (3t² − t) dt を x で微分しよう。', a: '3x² − x', exp: '3t² − t の原始関数を F(t) とすると、∫₂ˣ (3t² − t) dt = F(x) − F(2) です。F(2) は定数なので、x で微分すると F′(x) = 3x² − x となります。' },
      { err: 'グラフが途中で x 軸と交わるのに、区間全体を1つの定積分で計算して「面積」としてしまう。', why: '定積分の値は、x 軸より上の部分を正、下の部分を負として足し合わせたもので、面積とは一致しないことを忘れているからです。', fix: '面積を求めるときは、まずグラフをかいて x 軸との交点を見つけ、そこで区間を分けます。下にある部分は、マイナスをつけて(または上 − 下で)積分します。', q: '放物線 y = x(x − 2) と x 軸、および直線 x = 3 で囲まれた2つの部分の面積の和を求めよう(0 ≦ x ≦ 3 の範囲)。', a: '8/3', exp: '0 ≦ x ≦ 2 ではグラフが x 軸の下にあり、面積は ∫₀² (2x − x²)dx = 4/3。2 ≦ x ≦ 3 では上にあり、∫₂³ (x² − 2x)dx = 4/3。合計 8/3 です。∫₀³ x(x − 2)dx をそのまま計算すると 0 になってしまいます。' }
    ],
    essay: [
      { q: 'a を実数とする。f(a) = ∫₀¹ |x − a| dx とするとき、f(a) を a の式で表し、f(a) の最小値と、そのときの a の値を求めよ。', limit: '記述式(場合分けを示して答えよ)', hint: '|x − a| は x = a で式が切りかわります。a が積分の区間 0 ≦ x ≦ 1 の左にあるか、中にあるか、右にあるかで場合分けします。', model: '(ⅰ)a < 0 のとき、0 ≦ x ≦ 1 で x − a > 0 なので f(a) = ∫₀¹ (x − a)dx = 1/2 − a。\n(ⅱ)0 ≦ a ≦ 1 のとき、f(a) = ∫₀ᵃ (a − x)dx + ∫ₐ¹ (x − a)dx = a²/2 + (1 − a)²/2 = a² − a + 1/2。\n(ⅲ)a > 1 のとき、0 ≦ x ≦ 1 で x − a < 0 なので f(a) = ∫₀¹ (a − x)dx = a − 1/2。\n(ⅰ)では f(a) > 1/2、(ⅲ)でも f(a) > 1/2。\n(ⅱ)では f(a) = (a − 1/2)² + 1/4 なので、a = 1/2 のとき最小値 1/4 をとる。1/4 < 1/2 なので、これが全体の最小値である。\nよって、最小値は 1/4(a = 1/2 のとき)。', points: [['a の位置で3つに場合分けしている', 3], ['0 ≦ a ≦ 1 のとき、区間を x = a で分けて a² − a + 1/2 を求めている', 3], ['a < 0、a > 1 の場合の式を正しく求めている', 2], ['3つの場合を比べて最小値 1/4(a = 1/2)を答えている', 2]], ng: '絶対値をつけたまま積分したり、x = a で区間を分けずに計算したりする答案は得点できません。また、0 ≦ a ≦ 1 の場合の最小値だけを求めて、ほかの場合との比較をしないと減点されます。' }
    ],
    test: [
      { q: '不定積分 ∫(6x² + 2x)dx はどれ?(C は積分定数)', choices: ['12x + 2 + C', '2x³ + x² + C', '6x³ + 2x² + C', '3x³ + x² + C'], a: 'B(2x³ + x² + C)', exp: '∫x² dx = x³/3、∫x dx = x²/2 なので、6 × x³/3 + 2 × x²/2 + C = 2x³ + x² + C です。微分して確かめましょう。' },
      { q: '∫₀² (3x² − 1)dx を計算しよう。', a: '6', exp: '[x³ − x]₀² = (8 − 2) − 0 = 6 です。原始関数に上端を代入した値から、下端を代入した値を引きます。' },
      { q: '∫₁³ 2x dx を計算しよう。', a: '8', exp: '[x²]₁³ = 9 − 1 = 8 です。グラフで見ると、台形の面積 (2 + 6) × 2 ÷ 2 = 8 とも一致します。' },
      { q: '∫₋₂² (x³ + x²)dx を計算しよう。', a: '16/3', exp: 'x³ は奇関数なので −2 から 2 の積分は 0。x² は偶関数なので 2∫₀² x² dx = 2 × 8/3 = 16/3 です。' },
      { q: 'f′(x) = 3x² − 4、f(1) = 2 をみたす関数 f(x) を求めよう。', a: 'f(x) = x³ − 4x + 5', exp: 'f(x) = x³ − 4x + C。f(1) = 1 − 4 + C = 2 より C = 5 です。' },
      { q: '放物線 y = x² − 3x と x 軸で囲まれた部分の面積を求めよう。', a: '9/2', exp: '交点は x = 0、3。グラフは x 軸の下にあるので、面積は −∫₀³ (x² − 3x)dx = (3 − 0)³/6 = 27/6 = 9/2 です。' },
      { q: '放物線 y = x² と直線 y = 2x で囲まれた部分の面積を求めよう。', a: '4/3', exp: '交点は x = 0、2。0 ≦ x ≦ 2 で直線が上なので、∫₀² (2x − x²)dx = (2 − 0)³/6 = 4/3 です。' },
      { q: '∫₋₁² (x² − 2x)dx を計算しよう。', a: '0', exp: '[x³/3 − x²]₋₁² = (8/3 − 4) − (−1/3 − 1) = −4/3 + 4/3 = 0 です。x 軸の上と下の部分がちょうど打ち消し合っています。' },
      { q: 'f(x) = x + ∫₀¹ t f(t) dt をみたす関数 f(x) を求めよう。', a: 'f(x) = x + 2/3', exp: '∫₀¹ t f(t) dt は定数なので k とおくと f(x) = x + k。k = ∫₀¹ t(t + k)dt = 1/3 + k/2 より k = 2/3 です。' },
      { q: '2つの放物線 y = x² と y = −x² + 4 で囲まれた部分の面積を求めよう。', a: '16√2/3', exp: '交点は x² = 2 より x = ±√2。面積は ∫(4 − 2x²)dx(−√2 から √2)= 8√2 − 8√2/3 = 16√2/3 です。' }
    ],
    link: {
      prev: '微分(導関数の計算)が土台です。積分は微分の逆の計算なので、微分の公式をそのまま逆向きに使います。2次関数のグラフも、面積を求めるときに欠かせません。',
      next: '数学Ⅲでは、いろいろな関数の積分を学び、立体の体積や曲線の長さも求められるようになります。数学Bの数列の和は、細かく区切った長方形の面積の和を考える「区分求積法」で積分とつながります。',
      cross: [['物理', 'v-t グラフ(速度と時間のグラフ)と t 軸で囲まれた部分の面積は、移動距離を表します。速度を時間で積分すると、位置の変化が求められます。'], ['地学', '雨の強さ(1時間あたりの降水量)を時間で積分すると、その期間の総降水量になります。']],
      univ: '確率・統計では、連続的な量の確率を確率密度関数の積分で求めます。工学では、構造物にかかる力や、電気の量、物体の重心の位置などを積分で計算します。',
      readT: '2200年前の「1/6 公式」:アルキメデスの放物線の求積',
      read: '放物線と直線で囲まれた部分の面積を、積分を使わずに求めた人がいます。紀元前3世紀の古代ギリシャの数学者アルキメデスです。\nアルキメデスは『放物線の求積』という著作の中で、放物線と直線で囲まれた部分(放物線の切片)の面積が、その中に作れる特別な三角形の面積の 4/3 倍になることを証明しました。その三角形とは、切片の底辺の両はしと、底辺に平行な接線が放物線に接する点を結んだものです。\nアルキメデスの方法は、三角形の残りのすき間に、さらに小さな三角形を次々につめこんでいくものでした。新しく加わる三角形の面積の合計は、前の段階の 1/4 ずつになっていきます。その合計 1 + 1/4 + 1/16 + … を、限りなく続けた考え方で 4/3 と求めたのです。ニュートンやライプニッツより約1900年も前のことです。\n実際に、放物線 y = x² と直線で囲まれた面積を計算すると、交点の x 座標を α、β として (β − α)³/6 となり、これはちょうど、その三角形の面積の 4/3 倍になっています。教科書の「1/6 公式」は、アルキメデスの発見を積分で言いかえたものとも言えるのです。'
    }
  });
